eventScripts.script:
#we'll update the chkEvents dat aif it hasn't changed for over a minute	
if system.date.secondsBetween(currentValue.timeStamp, system.tag.read("[.]lastUpdated").value) > 60: system.tag.write("[.]updateChkEventData", 1)

return

if currentValue.value:

	import java.lang
	log = system.util.getLogger('kanoa_tag')
	tagValues = system.tag.readBlocking(["[.]debug", "[.]chkShtVersionGroupId", "[.]../Line/EquipID", "[.]../Line/OEE/itemId", "[.]../Line/OEE/shiftNameId"])
	debug = tagValues[0].value
	chkShtVersionGroupId = tagValues[1].value
	assetId = tagValues[2].value
	itemId = tagValues[3].value
	shiftNameId = tagValues[4].value
	errorMsg = ''
	timeNow = system.date.now()

	try:
		if chkShtVersionGroupId:
			if debug: log.info("%s tag change event looking for released check sheet version for chkShtVersionGroupId %s"%(tagPath, chkShtVersionGroupId))
			chkStates = system.kanoa.utilities.convertDatasetToDict(system.kanoa.quality.sheet.getStates({}), 'chkShtStateName', 'chkShtStateId')
			triggerTypeId = system.kanoa.utilities.getFieldValue('triggerTypeId', system.kanoa.quality.config.getTriggerTypes({'triggerTypeName': 'manual'}))
			userId = system.kanoa.security.getIDPUserId({'userName': 'tagChange'})
			chkShtId = system.kanoa.utilities.getFieldValue('chkShtId', system.kanoa.quality.sheet.getSheets({'chkShtVersionGroupId': chkShtVersionGroupId, 'chkShtVersionStateName': 'Released'}))
			if chkShtId: 
				chkEventInfo = {'chkShtId': chkShtId, 'assetId': assetId, 'itemId': itemId, 'chkShtTriggerId': None, 'triggerTypeId': triggerTypeId, 'shiftNameId': shiftNameId, 'comment': None, 'scheduledDate': system.date.now(), 'chkShtStateId': chkStates['Coming Due']}
				chkShtEventId = system.kanoa.quality.event.addCheckEvent(chkEventInfo, userId)
				if chkShtEventId is None:
					errorMsg = "addCheckEvent() didn't generate a chkShtEventId"
					if debug: log.warn(errorMsg)
				else:
					if debug: log.info("addCheckEvent() generated chkShtEventId %s"%chkShtEventId)
					count = system.kanoa.quality.schedule.updateScheduledAutoChecks()
					if count == 0 and debug: log.warn("updateScheduledAutoChecks() didn't execute any new check sheets")
			elif debug: log.warn("%s tag change event couldn't find a released check sheet version for chkShtVersionGroupId %s"%(tagPath, chkShtVersionGroupId))
		else: 
			errorMsg = 'Invalid chkShtVersionGroupId %s'%chkShtVersionGroupId
	except java.lang.Exception, e:
		errorMsg = e.cause
	except Exception, e:
		errorMsg = str(e)

	import time
	time.sleep(0.5)	#in case tag is being triggered manually, the change will be visible to the person

	if errorMsg: log.warn("%s timer script failed with %s"%(tagPath, errorMsg))
	system.tag.writeBlocking(["[.]lastUpdated", "[.]trigger", "[.]error"], [timeNow, 0, errorMsg])
	if debug: log.info("%s update took %sms"%(tagPath, system.date.millisBetween(timeNow, system.date.now())))

return
